import{_ as p,a0 as r,w as o,s as d,I as e,x as a,a1 as t,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200212 Extend the life of your SSD drive with fstrim","title":"在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命","tag":"202003","desc":""},"relativePath":"202003/20200212 Extend the life of your SSD drive with fstrim.md","filePath":"[post].md"}'),h={name:"202003/20200212 Extend the life of your SSD drive with fstrim.md"};function u(m,s,b,c,g,f){const i=r("Link");return o(),d("div",null,[s[21]||(s[21]=e("h1",{id:"在-linux-下使用-fstrim-延长-ssd-驱动器的寿命",tabindex:"-1"},[a("在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命 "),e("a",{class:"header-anchor",href:"#在-linux-下使用-fstrim-延长-ssd-驱动器的寿命","aria-label":"Permalink to “在 Linux 下使用 fstrim 延长 SSD 驱动器的寿命”"},"​")],-1)),s[22]||(s[22]=e("blockquote",null,[e("p",null,"这个新的系统服务可以使你的生活更轻松。")],-1)),s[23]||(s[23]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202003/04/121625sl380ga10g56d33h.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("在过去的十年中，固态驱动器（SSD）带来了一种管理存储的新方法。与上一代的转盘产品相比，SSD 具有无声、更冷却的操作和更快的接口规格等优点。当然，新技术带来了新的维护和管理方法。SSD 具有一种称为 TRIM 的功能。从本质上讲，这是一种用于回收设备上未使用的块的方法，该块可能先前已被写入，但不再包含有效数据，因此可以返回到通用存储池以供重用。Opensource.com 的 Don Watkins 首先在其 2017 年的文章《",-1)),t(i,{href:"https://linux.cn/article-8177-1.html"},{default:n(()=>[...s[0]||(s[0]=[a("Linux 固态驱动器：为 SSD 启用 TRIM",-1)])]),_:1}),s[2]||(s[2]=a("》中介绍过 TRIM 的内容。",-1))]),s[24]||(s[24]=l(`<p>如果你一直在 Linux 系统上使用此功能，则你可能熟悉下面描述的两种方法。</p><h3 id="老的方式" tabindex="-1">老的方式 <a class="header-anchor" href="#老的方式" aria-label="Permalink to “老的方式”">​</a></h3><h4 id="丢弃选项" tabindex="-1">丢弃选项 <a class="header-anchor" href="#丢弃选项" aria-label="Permalink to “丢弃选项”">​</a></h4><p>我最初使用 <code>mount</code> 命令的 <code>discard</code> 选项启用了此功能。每个文件系统的配置都放在 <code>/etc/fstab</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/fstab</span></span>
<span class="line"><span>UUID=3453g54-6628-2346-8123435f  /home  xfs  defaults,discard   0 0</span></span></code></pre></div><p>丢弃选项可启用自动的在线 TRIM。由于可能会对性能造成负面影响，最近关于这是否是最佳方法一直存在争议。使用此选项会在每次将新数据写入驱动器时启动 TRIM。这可能会引入其他磁盘活动，从而影响存储性能。</p><h4 id="cron-作业" tabindex="-1">Cron 作业 <a class="header-anchor" href="#cron-作业" aria-label="Permalink to “Cron 作业”">​</a></h4><p>我从 <code>fstab</code> 文件中删除了丢弃选项。然后，我创建了一个 cron 作业来按计划调用该命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -l</span></span>
<span class="line"><span>@midnight /usr/bin/trim</span></span></code></pre></div><p>这是我最近在 Ubuntu Linux 系统上使用的方法，直到我了解到另一种方法。</p><h3 id="一个新的-trim-服务" tabindex="-1">一个新的 TRIM 服务 <a class="header-anchor" href="#一个新的-trim-服务" aria-label="Permalink to “一个新的 TRIM 服务”">​</a></h3>`,11)),e("p",null,[s[4]||(s[4]=a("我最近发现有一个用于 TRIM 的 systemd 服务。Fedora 在版本 30 中将其",-1)),t(i,{href:"https://fedoraproject.org/wiki/Changes/EnableFSTrimTimer",title:"Fedora Project WIKI: Changes/EnableFSTrimTimer"},{default:n(()=>[...s[3]||(s[3]=[a("引入",-1)])]),_:1}),s[5]||(s[5]=a("，尽管默认情况下在版本 30 和 31 中未启用它，但计划在版本 32 中使用它。如果你使用的是 Fedora 工作站 31，并且你想要开始使用此功能，可以非常轻松地启用它。我还将在下面向你展示如何对其进行测试。该服务并非 Fedora 独有的服务。它是否存在及其地位将因发行版而异。",-1))]),s[25]||(s[25]=l(`<h4 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to “测试”">​</a></h4><p>我喜欢先进行测试，以更好地了解幕后情况。我通过打开终端并发出配置服务调用的命令来执行此操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/usr/sbin/fstrim --fstab --verbose --quiet</span></span></code></pre></div><p><code>fstrim</code> 的 <code>-help</code> 参数将描述这些信息和其他参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/sbin/fstrim --help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span> fstrim [options] &lt;mount point&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Discard unused blocks on a mounted filesystem.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span> -a, --all           trim all supported mounted filesystems</span></span>
<span class="line"><span> -A, --fstab         trim all supported mounted filesystems from /etc/fstab</span></span>
<span class="line"><span> -o, --offset &lt;num&gt;  the offset in bytes to start discarding from</span></span>
<span class="line"><span> -l, --length &lt;num&gt;  the number of bytes to discard</span></span>
<span class="line"><span> -m, --minimum &lt;num&gt; the minimum extent length to discard</span></span>
<span class="line"><span> -v, --verbose       print number of discarded bytes</span></span>
<span class="line"><span>     --quiet         suppress error messages</span></span>
<span class="line"><span> -n, --dry-run       does everything, but trim</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -h, --help          display this help</span></span>
<span class="line"><span> -V, --version       display version</span></span></code></pre></div><p>因此，现在我可以看到这个 systemd 服务已配置为在我的 <code>/etc/fstab</code> 文件中的所有受支持的挂载文件系统上运行该修剪操作（<code>-fstab</code>），并打印出所丢弃的字节数（<code>-verbose</code>），但是抑制了任何可能会发生的错误消息（<code>–quiet</code>）。了解这些选项对测试很有帮助。例如，我可以从最安全的方法开始，即空运行。我还将去掉 <code>-quiet</code> 参数，以便确定驱动器设置是否发生任何错误。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/sbin/fstrim --fstab --verbose --dry-run</span></span></code></pre></div><p>这就会显示 <code>fstrim</code> 命令根据在 <code>/etc/fstab</code> 文件中找到的文件系统要执行的操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/sbin/fstrim --fstab --verbose</span></span></code></pre></div><p>现在，这会将 TRIM 操作发送到驱动器，并报告每个文件系统中丢弃的字节数。以下是我最近在新的 NVME SSD 上全新安装 Fedora 之后的示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home: 291.5 GiB (313011310592 bytes) trimmed on /dev/mapper/wkst-home</span></span>
<span class="line"><span>/boot/efi: 579.2 MiB (607301632 bytes) trimmed on /dev/nvme0n1p1</span></span>
<span class="line"><span>/boot: 787.5 MiB (825778176 bytes) trimmed on /dev/nvme0n1p2</span></span>
<span class="line"><span>/: 60.7 GiB (65154805760 bytes) trimmed on /dev/mapper/wkst-root</span></span></code></pre></div><h4 id="启用" tabindex="-1">启用 <a class="header-anchor" href="#启用" aria-label="Permalink to “启用”">​</a></h4><p>Fedora Linux 实现了一个计划每周运行它的 systemd 计时器服务。要检查其是否存在及当前状态，请运行 <code>systemctl status</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status fstrim.timer</span></span></code></pre></div><p>现在，启用该服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable fstrim.timer</span></span></code></pre></div><h4 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to “验证”">​</a></h4><p>然后，你可以通过列出所有计时器来验证该计时器是否已启用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl list-timers --all</span></span></code></pre></div><p>会显示出下列行，表明 <code>fstrim.timer</code> 存在。注意，该计时器实际上激活了 <code>fstrim.service</code> 服务。这是实际调用 <code>fstrim</code> 的地方。与时间相关的字段显示为 <code>n/a</code>，因为该服务已启用且尚未运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NEXT   LEFT    LAST   PASSED   UNIT           ACTIVATES</span></span>
<span class="line"><span>n/a    n/a     n/a    n/a      fstrim.timer   fstrim.service</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>该服务似乎是在驱动器上运行 TRIM 的最佳方法。这比必须创建自己的 crontab 条目来调用 <code>fstrim</code> 命令要简单得多。不必编辑 <code>fstab</code> 文件也更安全。观察固态存储技术的发展很有趣，并且我很高兴看到 Linux 似乎正在朝着标准且安全的方向实现它。</p><p>在本文中，学习了固态驱动器与传统硬盘驱动器有何不同以及它的含义...</p><hr>`,25)),e("p",null,[s[7]||(s[7]=a("via: ",-1)),t(i,{href:"https://opensource.com/article/20/2/trim-solid-state-storage-linux"},{default:n(()=>[...s[6]||(s[6]=[a("https://opensource.com/article/20/2/trim-solid-state-storage-linux",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=a("作者：",-1)),t(i,{href:"https://opensource.com/users/alanfdoss"},{default:n(()=>[...s[8]||(s[8]=[a("Alan Formy-Duval",-1)])]),_:1}),s[13]||(s[13]=a(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 译者：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1}),s[15]||(s[15]=a(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[18]||(s[18]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[a("Linux中国",-1)])]),_:1}),s[20]||(s[20]=a(" 荣誉推出",-1))])])}const T=p(h,[["render",u]]);export{x as __pageData,T as default};
